function _checkMax(address _from) internal view returns (bool) {
        uint256 hashVal = _computeHash(abi.encodePacked(_from));
        bool exists;
        assembly {
            mstore(0, hashVal)
            mstore(32, _maxs.slot)
            exists := sload(keccak256(0, 64))
        }
        return exists;
